ALTER TABLE transactions ADD COLUMN adjusted_rate numeric;

UPDATE transactions t
SET adjusted_rate = m.esccomprate
FROM markets m
WHERE t.mktref = m.mktregistry;

CREATE INDEX idx_transactions_anomaly_detection 
ON transactions (mktref, txstatus, payamtusd, txfeeusd);

ALTER TABLE transactions ADD COLUMN adjusted_rate numeric;

UPDATE transactions t
SET adjusted_rate = m.interscore
FROM markets m
WHERE t.mktref = m.mktregistry;

CREATE INDEX idx_transactions_anomaly_detection 
ON transactions (mktref);

ALTER TABLE transactions ADD COLUMN mkt_rate numeric;

UPDATE transactions t
SET mkt_rate = m.esccomprate
FROM markets m
WHERE t.mktref = m.mktregistry;

CREATE INDEX idx_anomaly_detection ON transactions (mktref, txstatus);

ALTER TABLE transactions ADD COLUMN adjusted_esccomprate numeric;

UPDATE transactions t
SET adjusted_esccomprate = m.esccomprate
FROM markets m
WHERE t.mktref = m.mktregistry;

CREATE INDEX idx_anomaly_detection ON transactions (mktref, txstatus);
